(()=>{'use strict';const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};async function history(){const response=await fetch('/api/designer/engine'),data=await response.json();if(!response.ok)throw Error(data.error);const modules=$('business-engine-modules');modules.replaceChildren();for(const m of data.modules){const card=el('article');card.className='record';card.append(el('h3',m.name),el('p',m.skill),el('p',m.mode));modules.append(card);}const box=$('business-engine-history');box.replaceChildren();if(!data.runs.length)box.append(el('p','No workflow runs yet.'));for(const run of data.runs){const card=el('article');card.className='record';card.append(el('h3',new Date(run.createdAt).toLocaleString()),el('p',run.added+' tasks added · '+run.mode));for(const action of run.actions||[]){card.append(el('h4',action.title),el('p',action.status+' · '+action.deliverable),el('p','Evidence: '+action.evidence));}card.append(el('p',run.notice));box.append(card);}return data;}
$('refresh-business-engine').onclick=()=>history().then(d=>{$('business-engine-status').textContent=d.model;}).catch(e=>{$('business-engine-status').textContent=e.message;});$('run-business-engine').onclick=async()=>{const b=$('run-business-engine');b.disabled=true;let release;try{release=window.bongaRunGate.begin();const response=await fetch('/api/designer/engine',{method:'POST'}),result=await response.json();if(!response.ok)throw Error(result.error);$('business-engine-status').textContent=result.added+' proposed tasks saved. Reloading your cloud workspace…';document.dispatchEvent(new CustomEvent('designer-cloud-changed'));location.hash='#my-work';location.reload();}catch(e){$('business-engine-status').textContent=e.message||'Workflow unavailable.';b.disabled=false;}finally{release?.();}};})();
